@page "/chat"
@rendermode InteractiveServer
@using sv_8abc57deba3d4bcabbb7c810d88d87c7.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannel?.Id ?? 0"
                    OnChannelSelected="SelectChannel" />

    <div class="message-area @(threadRootMessage is null ? "expanded" : "")">
        @if (selectedChannel is not null)
        {
            <div class="message-area-header">
                <h2># @selectedChannel.Name</h2>
                <p>@selectedChannel.Description</p>
            </div>

            <div class="message-list" @onscroll="HandleScroll">
                @if (isLoadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @foreach (var message in messages)
                {
                    <MessageBubble Message="message"
                                   ReplyCount="GetReplyCount(message.Id)"
                                   OnOpenThread="OpenThread"
                                   OnReact="(emoji) => AddReaction(message.Id, emoji)" />
                }
            </div>

            <MessageInput Placeholder="@($"Message #{selectedChannel.Name}")"
                          OnSend="SendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, int> replyCounts = new();
    private bool isLoadingMore;
    private bool hasMoreMessages = true;
    private const int PageSize = 30;

    // Thread state
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messages = [];
        replyCounts.Clear();
        hasMoreMessages = true;

        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Update unread count locally
        var idx = channels.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }
    }

    private async Task LoadMessages()
    {
        if (selectedChannel is null) return;

        var loaded = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        if (loaded.Count < PageSize)
        {
            hasMoreMessages = false;
        }

        messages.InsertRange(0, loaded);
        UpdateReplyCounts();
    }

    private void UpdateReplyCounts()
    {
        replyCounts.Clear();
        foreach (var msg in messages.Where(m => m.ReplyToId.HasValue))
        {
            var rootId = msg.ReplyToId!.Value;
            replyCounts.TryGetValue(rootId, out var count);
            replyCounts[rootId] = count + 1;
        }
    }

    private int GetReplyCount(int messageId)
    {
        replyCounts.TryGetValue(messageId, out var count);
        return count;
    }

    private async Task HandleScroll()
    {
        // Triggered on scroll — in a real app, JS interop would detect scroll-to-top
        // For now, we provide a load-more mechanism
        if (!isLoadingMore && hasMoreMessages)
        {
            isLoadingMore = true;
            await LoadMessages();
            isLoadingMore = false;
        }
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var message = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(Message rootMessage)
    {
        threadRootMessage = rootMessage;
        threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
    }

    private void CloseThread()
    {
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannel is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        messages.Add(reply);
        UpdateReplyCounts();
    }

    private async Task AddReaction(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        // Optimistic update
        var msg = messages.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, ["You"]));
            }
        }
    }
}

